/**
 * The built-in background music: a short looping pad (A minor chord with a slow swell) generated by arithmetic,
 * so the repository holds no audio file and nothing is copyrighted. It is NOT an AI model's output (it is a few
 * lines of sine waves), but it is a generated work and is recorded in SOURCES.md as such.
 *
 * Deterministic: only integer sample indices and Math.sin (V8's fdlibm port, identical on every platform) go in,
 * 16-bit integers come out, so the bytes and their sha256 never change. A test pins the sha256.
 */
export const MUSIC_RATE = 48000;
export const MUSIC_SECONDS = 10;
/** sha256 of builtinMusicWav(). The rules parser uses it as the music asset id; a media test recomputes and compares. */
export const BUILTIN_MUSIC_SHA256 = "19c234fef199c51cd59f5a1365f7c09ff83d8a2a8352751a5fc6668e7e739cbb";

export function builtinMusicWav(): Uint8Array {
  const n = MUSIC_RATE * MUSIC_SECONDS;
  const data = new Int16Array(n * 2);
  // Whole numbers of cycles in 10 s (frequencies are multiples of 0.1 Hz), so the loop point is seamless.
  const notes = [220.0, 261.6, 329.6, 440.0];
  for (let i = 0; i < n; i++) {
    const t = i / MUSIC_RATE;
    const swell = 0.6 + 0.4 * Math.sin((2 * Math.PI * t) / MUSIC_SECONDS); // one slow swell per loop
    let l = 0;
    let r = 0;
    notes.forEach((f, k) => {
      const s = Math.sin(2 * Math.PI * f * t);
      l += s * (k % 2 === 0 ? 1 : 0.7);
      r += s * (k % 2 === 0 ? 0.7 : 1);
    });
    data[2 * i] = Math.round((l / 4) * swell * 0.8 * 32767);
    data[2 * i + 1] = Math.round((r / 4) * swell * 0.8 * 32767);
  }
  const bytes = new Uint8Array(44 + data.byteLength);
  const v = new DataView(bytes.buffer);
  const tag = (o: number, s: string) => [...s].forEach((c, i) => (bytes[o + i] = c.charCodeAt(0)));
  tag(0, "RIFF");
  v.setUint32(4, 36 + data.byteLength, true);
  tag(8, "WAVE");
  tag(12, "fmt ");
  v.setUint32(16, 16, true);
  v.setUint16(20, 1, true); // PCM
  v.setUint16(22, 2, true);
  v.setUint32(24, MUSIC_RATE, true);
  v.setUint32(28, MUSIC_RATE * 4, true);
  v.setUint16(32, 4, true);
  v.setUint16(34, 16, true);
  tag(36, "data");
  v.setUint32(40, data.byteLength, true);
  for (let i = 0; i < data.length; i++) v.setInt16(44 + 2 * i, data[i]!, true);
  return bytes;
}
